import re
from builtins import str as text

try:
    from collections.abc import Iterable
except ImportError:
    from collections import Iterable  # type: ignore
from taf.collectors.l1l2bip.factory import L1L2BIPCollectorFactory, ASODL1L2BIPCollectorFactory, \
    GenericL1L2BIPCollectorFactory, InterfaceL1L2BIPCollectorFactory, AirphoneL1L2BIPCollectorFactory, \
    VduInterfaceMirroringL1L2BIPCollectorFactory
from taf.collectors.core import core
from robot.utils.robottypes import is_truthy
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class l1l2bip(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    @staticmethod
    def _iterable(arg):
        return (isinstance(arg, Iterable)
                and not isinstance(arg, bytes)
                and not isinstance(arg, text))

    @staticmethod
    def _string(arg):
        return arg.decode("utf-8") if isinstance(arg, bytes) else str(arg)

    def _int_list(self, arg):
        return [
            int(x) for x in re.findall(
                r"\d+", self._string(list(arg) if self._iterable(arg) else arg))]

    @staticmethod
    def _call_factory_class(factory_class_instance, configuration, existing_arguments):
        return factory_class_instance.create(configuration=configuration,
                                             existing_arguments=existing_arguments)

    def create_l1l2bip_collector(
            self,
            name,
            executor,
            collector,
            mirroring_mode=None,
            gnb_mirroring_path=None,
            gnb_mirroring_config_path=None,
            enable_syscom_mirroring=None,
            mirror_capacity_units=None,
            carrier_aggregation=None,
            script_dir=None):
        """
        Create L1/L2 BIP Collector from given configuration

        :param str name: name of collector
        :param dict executor: ASIK control machine info host, user, password
        :param str collector: alias of previously created tcpdump
        :param str mirroring_mode: gnb mirroring mode ("manual"|"remote"),
                                            default value: "manual"
        :param str gnb_mirroring_path: path of gnbMirroring script,
                                            default value: "/opt/gnbmirroring/gnbMirroring.sh"
        :param str gnb_mirroring_config_path: (optional) path of gnbMirroringConfig script,
                                            default value: "/opt/gnbmirroring/gnbMirroringConfig.sh"
        :param str enable_syscom_mirroring: (optional) mirroring syscom traffic between ASIK and ABIL,
                                            default value: "true"
        :param list mirror_capacity_units: comma-separated list of capacity units to be mirrored, default: "1";
                                           example: [1,3] means mirror ABIL 1 and 3, but not ABIL 2.
        :param str carrier_aggregation: (optional) for GC2/GD2 L2-RT instances, default "false"
        :param str script_dir: (optional) script folder in node, default vlaue: "/ffs/run/config/scripts"

        :return: L1L2BIPCollector : created object of L1L2BIPCollector

        Note: Keyword create_l1l2bip_collector is deprecated. Please use create_interface_mirroring_l1l2bip_collector instead.
        """

        logger.warning(
            "The create_l1l2bip_collector keyword is deprecated. \
            Please use create_interface_mirroring_l1l2bip_collector."
        )
        configuration = {"name": name,
                         "executor": executor}
        if mirroring_mode is not None:
            if mirroring_mode not in ["manual", "remote"]:
                raise RuntimeError(
                    "User has given wrong option ({}) for mirroring_mode".format(mirroring_mode))
            configuration["mirroring_mode"] = mirroring_mode
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["gnb_mirroring_path", "gnb_mirroring_config_path", "enable_syscom_mirroring",
                                  "mirror_capacity_units", "carrier_aggregation", "script_dir"]:
                if parameter_value is not None:
                    configuration[parameter_name] = parameter_value
        logger.info("Creating L1/L2 BIP Collector with alias name" + name)
        existing_arguments = {"collector": self.get_alias_value(collector)}
        l1l2bip = self._call_factory_class(L1L2BIPCollectorFactory(), configuration, existing_arguments)
        logger.info("L1/L2 BIP Collector created successfully")
        self.set_alias(name, l1l2bip)

    def create_asod_l1l2bip_collector(
            self,
            name,
            executor,
            collector,
            asod_mirroring_path,
            script_dir=None):
        """
        Create ASOD L1/L2 BIP Collector from given configuration

        :param str name: name of collector
        :param dict executor: ASOD control machine info host, user, password
        :param str collector: alias of previously created tcpdump
        :param str asod_mirroring_path: path of ASODMirroring script
        :param str script_dir: (optional) script folder in node, default vlaue: "/ffs/run/config/scripts"

        :return: ASODL1L2BIPCollector : created object of ASODL1L2BIPCollector

        Note: Keyword create_asod_l1l2bip_collector is deprecated.Please use create_interface_mirroring_l1l2bip_collector instead.
        """

        logger.warning(
            "The create_asod_l1l2bip_collector keyword is deprecated. \
            Please use create_interface_mirroring_l1l2bip_collector.")
        configuration = {"name": name,
                         "executor": executor,
                         "asod_mirroring_path": asod_mirroring_path}
        if script_dir is not None:
            configuration["script_dir"] = script_dir
        logger.info("Creating ASOD L1/L2 BIP Collector with alias name" + name)
        existing_arguments = {"collector": self.get_alias_value(collector)}
        l1l2bip = self._call_factory_class(ASODL1L2BIPCollectorFactory(), configuration,
                                           existing_arguments)
        logger.info("ASOD L1/L2 BIP Collector created successfully")
        self.set_alias(name, l1l2bip)

    def create_generic_l1l2bip_collector(self,
                                         name,
                                         executor,
                                         collector,
                                         setup_commands,
                                         teardown_commands=None):
        """
        Create Generic L1/L2 BIP Collector from given configuration

        :param str name: name of collector
        :param dict executor: mirror script executor info host, user, password
        :param str collector: alias of previously created tcpdump
        :param list setup_commands: commands need to executed during setup
        :param list teardown_commands: commands need to executed during teardown


        :return: GenericL1L2BIPCollector : created object of GenericL1L2BIPCollector

        Please refer https://confluence.ext.net.nokia.com/pages/viewpage.action?pageId=1014283497 for detail.
        """

        configuration = {"name": name,
                         "executor": executor,
                         "setup_commands": setup_commands}
        if teardown_commands is not None:
            configuration["teardown_commands"] = teardown_commands
        logger.info("Creating Generic L1/L2 BIP Collector with alias name" + name)
        existing_arguments = {"collector": self.get_alias_value(collector)}
        l1l2bip = self._call_factory_class(GenericL1L2BIPCollectorFactory(), configuration,
                                           existing_arguments)
        logger.info("Generic L1/L2 BIP Collector created successfully")
        self.set_alias(name, l1l2bip)

    def create_interface_mirroring_l1l2bip_collector(self,
                                                     name,
                                                     webservice,
                                                     interface=None,
                                                     destination=None,
                                                     nr_phy_cell_ids=None,
                                                     nr_cell_dns=None,
                                                     remove_zip_file=None,
                                                     target_file_name=None,
                                                     merge_pcap_files=None,
                                                     timeout=None,
                                                     parallel_mirroring=None,
                                                     mirroring_filter=None,
                                                     specific_message_ids=None):

        """
        Create BIP trace collector, that uses ADMIN API request "interfaceMirroring".

        :param str name: name of collector
        :param dict webservice: ADMIN API setup info, see `setup_admin <https://\
                                taf-sbts-oam-coam-admin.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/\
                                interface.html#taf.sbts.oam.coam.admin.interface.admin.setup_admin>`_,
                                additionally the following parameter name abbreviations are supported:
                                * "host" instead of "bts_host"
                                * "port" instead of "bts_port"
                                * "user" instead of "username"
        :param str interface: (Optional) either "L1-L2" or "L2Hi-L2Lo", default value "L1-L2"
        :param str destination: (Optional) either "Local" or "Remote, default value "Local"
        :param Union(list, str) nr_phy_cell_ids: (Optional) list of physical cell ids. If given ensure cell is on air
                                                 before running the setup. If not given it will check nr_cell_dns.

        :param list nr_cell_dns:(Optional) list of cell DNs. By default it takes all cells or ignored if
                                nr_phy_cell_ids is given. operator can select up to 8 NR cells.

                The same cell can be specified in 3 different formats. e.g :

                - nrCellDNs -NIDD Path ->  nr_cell_dns=["MRBTS-1/NRBTS-1/NRCELL-1"]
                - nrCellDNs -full _A Path -> nr_cell_dns=["/MRBTS-1/RAT-1/BTS_L-4/BTS_CONF-1/NP-1/SCF-1/MRBTS_A-1/NRBTS_A-1/NRCELL_A-1"]
                - nrCellDNs -full _R Path -> nr_cell_dns=["/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/NRBTS_R-1/NRCELL_R-1"]

            Please refer https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-interfaceMirroring.html
            for more info.

        :param bool remove_zip_file: (optional)  whether the zip file shall be kept or deleted after extracting all
                                     contained pcap files default: True files will be deleted.
        :param str target_file_name: (optional) file name part of the path under which the pcap file is stored locally
                                     during collect_collectors, default: "[collector_name].pcap"
        :param bool merge_pcap_files: (optional) whether the pcap files should be merged or not
                                     default: True files will be merged.
        :param int timeout: Time in seconds to wait for positive procedure result, default to 60s
        :param bool parallel_mirroring: Optional, Only available from SBTS23R3 onwards.
        :param str mirroring_filter: Optional, ["Default" | "AllMessages" | "SpecificL1L2Messages"].
                                        Only supported when interface is 'L1-L2' and destination is 'Local'.
                                        Only available from SBTS24R1 onwards.
        :param str specific_message_ids: Optional, only supported when mirroring_filter is 'SpecificL1L2Messages'.
                                          string using comma separate. Must be in hex format. e.g :
                                          '0xE3F3,0x0A00'
        """
        configuration = {"name": name,
                         "webservice": webservice}
        nr_phy_cell_ids = self._int_list(nr_phy_cell_ids) if nr_phy_cell_ids else None
        specific_message_ids = [id.strip() for id in specific_message_ids.split(",")] if specific_message_ids else None
        timeout = float(timeout) if timeout else None
        remove_zip_file = is_truthy(remove_zip_file) if remove_zip_file else None
        parallel_mirroring = is_truthy(parallel_mirroring) if parallel_mirroring else None
        merge_pcap_files = is_truthy(merge_pcap_files) if merge_pcap_files else None
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["interface", "destination", "nr_phy_cell_ids", "nr_cell_dns",
                                  "remove_zip_file", "target_file_name", "timeout",
                                  "merge_pcap_files", "parallel_mirroring", "mirroring_filter",
                                  "specific_message_ids"] and parameter_value is not None:
                configuration[parameter_name] = parameter_value
        logger.info("Creating interface mirroring L1/L2 BIP Collector with alias name" + name)
        l1l2bip = self._call_factory_class(InterfaceL1L2BIPCollectorFactory(), configuration,
                                           {})
        logger.info("interface mirroring L1/L2 BIP Collector created successfully")
        self.set_alias(name, l1l2bip)

    def create_airphone_l1l2bip_collector(
            self,
            name,
            executor,
            collector,
            script_paths,
            command_line=None,
            script_dir=None):
        """
        Create Airphone L1/L2 BIP Collector from given configuration

        :param str name: name of collector
        :param dict executor: Airphone common module info host, user, password
        :param str collector: alias of previously created collector (e. g. tcpdump collector)
        :param list script_paths: paths of scripts (or other files) to be transfered to "script_dir" on AirPhone
        :param str or Dict command_line: (optional) command line to execute to enable mirroring;
                                 it will allow either string single command executed in the setup
                                 or a  dictionary which allows commands that are executed in setup and tear down .
                                 by default value: basename of first element of "script_paths", e. g. if "script_paths"
                                 is ["/tmp/apMirroring.sh", "/tmp/apMirroringConfig.sh"] and "command_line" is not
                                 given, then "command_line" gets the value "./apMirroring.sh"; starting "tcpdump"
                                 from inside apMirroring.sh is not supported by this collector, i. e. omitting
                                 "command_line" requires MIRRORING_MODE='manual' in "apMirroringConfig.sh"
        :param str script_dir: (optional) script folder in AirPhone common module,
                               default value: "/ffs/run/config/scripts"
        """

        configuration = {"name": name,
                         "executor": executor}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["script_paths", "script_dir", "command_line"]:
                if parameter_value is not None:
                    configuration[parameter_name] = parameter_value
        logger.info("Creating Airphone L1/L2 BIP Collector with alias name" + name)
        existing_arguments = {"collector": self.get_alias_value(collector)}
        l1l2bip = self._call_factory_class(AirphoneL1L2BIPCollectorFactory(), configuration,
                                           existing_arguments)
        logger.info("Airphone L1/L2 BIP Collector created successfully")
        self.set_alias(name, l1l2bip)

    def create_vdu_interface_mirroring_l1l2bip_collector(self,
                                                         name,
                                                         webservice,
                                                         interface=None,
                                                         nr_phy_cell_ids=None,
                                                         nr_cell_dns=None,
                                                         remove_zip_file=None,
                                                         timeout=None):
        """
        Create BIP trace collector, that uses VDU OAMCU REST API request "/traces/u-plane/interface-mirroring".

        :param str name: name of collector
        :param dict webservice: ADMIN API setup info, see `connect_to <https://\
                                taf-gnb-oam-coam-vdu.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/\
                                interface.html#taf.gnb.oam.coam.vdu.interface.vdu.connect_to>`_,
                                additionally the following parameter name abbreviations are supported:
                                * "user" instead of "username"
                                * "release" instead of "vdu_version"
        :param str interface: (Optional) either "L1-L2" or "L2Hi-L2Lo", default value "L1-L2"
        :param Union[list, str] nr_phy_cell_ids: (Optional) list of physical cell ids. If given ensure cell is on air
                                                 before running the setup. If not given it will check nr_cell_dns.
        :param list nr_cell_dns: (Optional) list of cell DNs. By default it takes all cells or ignored if
                                 nr_phy_cell_ids is given. Operator can select up to 8 NR cells.
                                 For example: [‘MRBTS-1/NRBTS-1/NRCELL-1’]
        :param bool remove_zip_file: (optional)  whether the zip file shall be kept or deleted after extracting all
                                     contained pcap files default: True files will be deleted.
        :param int timeout: Time in seconds to wait for positive procedure result, default to 60s
        :raises HTTPError: if argument usage_state="inactive" and interface mirroring is already inactive
        """
        configuration = {"name": name,
                         "webservice": webservice}
        nr_phy_cell_ids = self._int_list(nr_phy_cell_ids) if nr_phy_cell_ids else None
        timeout = float(timeout) if timeout else None
        remove_zip_file = is_truthy(remove_zip_file) if remove_zip_file else None
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["interface", "nr_phy_cell_ids", "nr_cell_dns",
                                  "remove_zip_file", "timeout"] and parameter_value is not None:
                configuration[parameter_name] = parameter_value
        logger.info("Creating vdu interface mirroring L1/L2 BIP Collector with alias name" + name)
        l1l2bip = self._call_factory_class(VduInterfaceMirroringL1L2BIPCollectorFactory(), configuration,
                                           {})
        logger.info("Vdu interface mirroring L1/L2 BIP Collector created successfully")
        self.set_alias(name, l1l2bip)
